package interium.core;
public final class ModuleMathTest {
 private static int checks;private static void eq(double a,double b){checks++;if(!Double.isFinite(a)||Math.abs(a-b)>1e-8)throw new AssertionError(a+" != "+b);}
 public static void main(String[] args){eq(ModuleMath.snap(Double.NaN,0,10,.1),0);eq(ModuleMath.snap(15,0,10,.1),10);eq(ModuleMath.snap(-4,0,10,.1),0);eq(ModuleMath.snap(.26,0,1,.1),.3);eq(ModuleMath.wrap(359),-1);eq(ModuleMath.wrap(-359),1);eq(ModuleMath.turn(-120,60,1),-60);eq(ModuleMath.turn(10,60,.25),2.5);eq(ModuleMath.quantize(1.1,.25),1);eq(ModuleMath.quantize(-1.1,.25),-1);eq(ModuleMath.entityImpulse(8,2),.16);eq(ModuleMath.entityImpulse(8,0),0);eq(ModuleMath.direction(0,0,1)[0],0);eq(ModuleMath.direction(3,4,.5)[0],.3);eq(ModuleMath.direction(3,4,.5)[1],.4);for(int i=0;i<=1000;i++){double x=i/1000d,v=ModuleMath.snap(x*3-1,0,1,.05);checks++;if(v<0||v>1)throw new AssertionError("slider bounds");long a=ModuleMath.interval(8,12,x);eq(a,ModuleMath.interval(12,8,x));checks++;if(a<83333333||a>125000000)throw new AssertionError("CPS bounds");double[] d=ModuleMath.direction(i+1,-i,.32);eq(Math.hypot(d[0],d[1]),.32);}System.out.println("PASS: "+checks+" module policy checks (not world/server/FPS tests)");}
}
